executionCode:
return {
  name: node.properties.toolName?.value || 'json_query',
  description: node.properties.toolDescription?.value || 'Query JSON with JSONPath',
  enabled: node.properties.enabled?.value !== false,
  schema: {
    type: 'object',
    properties: {
      jsonData: {
        type: 'object',
        description: 'The JSON object to query'
      },
      path: {
        type: 'string',
        description: 'JSONPath expression (e.g., "$.users[*].name")'
      }
    },
    required: ['jsonData', 'path']
  },
  code: `const jp = require('jsonpath');
const result = jp.query(args.jsonData, args.path);
return { path: args.path, matches: result, count: result.length };`
};
